/*
 * Host run of every NIST ACVP ML-DSA test case, for the three parameter
 * sets, plus randomized round trips and boundary cases.
 *
 * The test logic is examples/mldsa_test_vectors/acvp_runner.h, the same file
 * the Arduino sketch uses. Here it runs against acvp_all.h, generated by
 * scripts/gen_acvp_vectors.py --all --full-expected.
 *
 * SPDX-License-Identifier: Apache-2.0
 */

#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <cstdlib>

static void acvp_sha256(const uint8_t *, size_t, uint8_t[32]) {
  std::fprintf(stderr, "a SHA-256 digest was requested, but the host vectors "
                       "must carry full expected values\n");
  std::abort();
}

static void acvp_fail(const char *what, unsigned id) {
  std::printf("  [FAIL] %s (id %u)\n", what, id);
}

#include "acvp_all.h"
#include "acvp_runner.h"

static const int ROUNDS = 10;
static int totalPass = 0, totalFail = 0;

template <unsigned L, size_t NKG, size_t NSG, size_t NSV>
static void runLevel(const acvp_keygen_t (&keygen)[NKG],
                     const acvp_siggen_t (&siggen)[NSG],
                     const acvp_sigver_t (&sigver)[NSV]) {
  acvp::Result r;
  for (const acvp_keygen_t &t : keygen) acvp::keyGen<L>(r, t);
  for (const acvp_siggen_t &t : siggen) acvp::sigGen<L>(r, t);
  for (const acvp_sigver_t &t : sigver) acvp::sigVer<L>(r, t);
  int acvpChecks = r.pass + r.fail;
  acvp::roundTrips<L>(r, ROUNDS);
  acvp::edgeCases<L>(r);
  std::printf("ML-DSA-%u: keyGen %zu, sigGen %zu, sigVer %zu ACVP cases; "
              "%d further checks -> %d passed, %d failed\n",
              L, NKG, NSG, NSV, r.pass + r.fail - acvpChecks, r.pass, r.fail);
  totalPass += r.pass;
  totalFail += r.fail;
}

int main() {
  runLevel<44>(acvp_keygen_44, acvp_siggen_44, acvp_sigver_44);
  runLevel<65>(acvp_keygen_65, acvp_siggen_65, acvp_sigver_65);
  runLevel<87>(acvp_keygen_87, acvp_siggen_87, acvp_sigver_87);
  std::printf("ACVP and edge cases: %d passed, %d failed\n", totalPass, totalFail);
  return totalFail == 0 ? 0 : 1;
}
